#include <Wire.h>
#include <DHT.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>

#define DHTPIN 2
#define DHTTYPE DHT11

const int RELAY = 7;               // active LOW
const float BATAS_ATAS = 30.0;     // kipas ON di atas suhu ini
const float BATAS_BAWAH = 28.0;    // kipas OFF di bawah suhu ini

DHT dht(DHTPIN, DHTTYPE);
Adafruit_SSD1306 display(128, 64, &Wire, -1);
bool kipasNyala = false;

void setup() {
  pinMode(RELAY, OUTPUT);
  digitalWrite(RELAY, HIGH);       // kipas mati
  dht.begin();
  if (!display.begin(SSD1306_SWITCHCAPVCC, 0x3C)) {
    while (true);
  }
  display.setTextColor(WHITE);
}

void loop() {
  float t = dht.readTemperature();

  if (!isnan(t)) {
    if (t >= BATAS_ATAS) kipasNyala = true;
    else if (t <= BATAS_BAWAH) kipasNyala = false;
    digitalWrite(RELAY, kipasNyala ? LOW : HIGH);
  }

  display.clearDisplay();
  display.setTextSize(1);
  display.setCursor(0, 0);
  display.println(F("Kipas Otomatis"));

  display.setTextSize(2);
  display.setCursor(0, 20);
  if (isnan(t)) display.print(F("Error"));
  else { display.print(t, 1); display.print(F(" C")); }

  display.setTextSize(1);
  display.setCursor(0, 52);
  display.print(F("Kipas: "));
  display.println(kipasNyala ? F("ON") : F("OFF"));
  display.display();
  delay(2000);
}
